// Editor: the race below is an exception on the very first run.
// Player: no safety handles, no checks. CenterJob reads pos
// while MoveJob is half-way through writing it. Nothing is reported.

// Your own checks: compiled out of the Player together with Unity's
[Conditional("ENABLE_UNITY_COLLECTIONS_CHECKS")]
static void CheckIndex(int i, int length)
{
    if ((uint)i >= (uint)length)
        throw new ArgumentOutOfRangeException("index");
}

// Edit > Preferences > Jobs > Enable Jobs Debugger
//     conflicts between jobs and with the main thread (Editor only)
// Jobs > Burst > Enable Safety Checks: Off / On / Force On
//     checks inside Burst-compiled code; back to On after an Editor reload

[BurstCompile(DisableSafetyChecks = true)]   // this job only; Force On overrides it
struct HotJob : IJobParallelFor
{
    public NativeArray<float> data;
    public void Execute(int i) => data[i] *= 2f;
}

[BurstCompile]
struct SplitJob : IJobParallelFor
{
    [ReadOnly] public NativeArray<float2> segments;
    // job i writes 2*i and 2*i+1: no overlap by construction, but not [i]
    [NativeDisableParallelForRestriction] public NativeArray<float> ends;

    public void Execute(int i)
    {
        ends[2 * i]     = segments[i].x;
        ends[2 * i + 1] = segments[i].y;
    }
}

// [NativeDisableContainerSafetyRestriction] - no checks at all for this field
