[BurstCompile]
struct CenterJob : IJob
{
    [ReadOnly] public NativeArray<float3> pos;   // CenterJob only reads pos
    public NativeReference<float3> center;

    public void Execute()
    {
        float3 s = float3.zero;
        for (int i = 0; i < pos.Length; i++) s += pos[i];
        center.Value = s / pos.Length;
    }
}

public class Swarm : MonoBehaviour
{
    NativeArray<float3> pos, vel;      // allocated in Awake
    NativeReference<float3> center;
    JobHandle handle;

    void Update()
    {
        var move = new MoveJob { pos = pos, vel = vel, dt = Time.deltaTime };
        var avg = new CenterJob { pos = pos, center = center };
        JobHandle moved = move.Schedule(pos.Length, 64);
        handle = avg.Schedule(moved);  // starts after MoveJob
        JobHandle.ScheduleBatchedJobs();
    }

    void LateUpdate()
    {
        handle.Complete();             // completes MoveJob too
        Debug.Log(center.Value);
    }
}
